question:
What is the output of the following C++ code?
#include <iostream>
using namespace std;
class Base {
public:
    void show() { cout << "Base "; }
};
class Derived : public Base {
public:
    void show() { cout << "Derived "; }
};
int main() {
    Base* ptr = new Derived();
    ptr->show();
    delete ptr;
    return 0;
}

What is the output of the following C++ code?
#include <iostream>
using namespace std;
class Base {
public:
    virtual void show() { cout << "Base "; }
};
class Derived : public Base {
public:
    void show() override { cout << "Derived "; }
};
int main() {
    Base* ptr = new Derived();
    ptr->show();
    delete ptr;
    return 0;
}

